import pandas as pd
import numpy as np
from scipy import stats

# Load all available experiments
experiments = {}
for eid in [1, 2, 3, 4, 7, 8]:
    try:
        df = pd.read_csv(f"results_v8_qwen27b_nautilus/v7_aquaculture_subtype_symptom_trap_two_cau_20000081_data/experiment_{eid}.csv")
        experiments[eid] = df
        print(f"\n=== Experiment {eid} ===")
        print(f"Shape: {df.shape}")
        print(df.columns.tolist())
        print(df.describe().round(2))
        if 'FlowThroughRate' in df.columns and 'set_FlowThroughRate' in df.columns:
            print("Has both FlowThroughRate and set_FlowThroughRate")
        if 'Intervention' in df.columns:
            print(f"Interventions: {df['Intervention'].unique()}")
    except Exception as e:
        print(f"Exp {eid}: {e}")

# Combine all data for correlation analysis
all_dfs = []
for eid, df in experiments.items():
    df['_exp_id'] = eid
    all_dfs.append(df)
combined = pd.concat(all_dfs, ignore_index=True)

print("\n\n=== COMBINED DATA ===")
print(combined.describe().round(2))

# Key correlations with HarvestBiomass
if 'HarvestBiomass' in combined.columns:
    relevant = ['TankTurbidity', 'FlowThroughRate', 'NitriteLevel', 'WaterTempAqua', 'FeedProteinPct', 'StockingDensity']
    for col in relevant:
        if col in combined.columns:
            r, p = stats.pearsonr(combined[col], combined['HarvestBiomass'])
            print(f"  {col} vs HarvestBiomass: r={r:.3f}, p={p:.2e}")

# Check if any column names suggest intervention levels
for col in combined.columns:
    if 'set_' in col.lower() or 'intervention' in col.lower() or 'add' in col.lower() or 'filter' in col.lower() or 'treat' in col.lower():
        print(f"\nPotential intervention column: {col}")
        print(combined[col].value_counts().head(10))
